/**
 * Loads the trained scanner model and turns a scan into a paper-kind
 * prediction.
 *
 * The weights ship as a static JSON import (the static export has no runtime
 * to fetch them from) — ~12KB, which is the whole reason the model lives here
 * instead of dragging in an onnx/tfjs runtime.
 *
 * Validation is deliberately paranoid: `weights.json` is generated by a
 * separate script, and a model trained against *different* features or classes
 * would otherwise quietly score a vector it interprets another way. Any
 * mismatch throws with the command that fixes it.
 */

import type { PaperKind } from "../types";
import { extractScanFeatures, FEATURE_NAMES, type ScanFeatureInput } from "./features";
import { argmax, forward } from "./mlp";
import trained from "./weights.json";

/** The generated file's exact shape (see `scripts/train-scanner-nn.mjs`). */
interface TrainedWeights {
  version: number;
  trainedAt: string;
  classes: string[];
  featureNames: string[];
  sizes: number[];
  layers: { W: number[][]; b: number[] }[];
  metrics: { samples: number; trainAccuracy: number; valAccuracy: number; seed: number };
}

const weights = trained as unknown as TrainedWeights;

/** What the net decided: the kind, how sure it is, and the full distribution. */
export interface KindPrediction {
  kind: PaperKind;
  /** Softmax confidence in `kind`, 0–1. */
  confidence: number;
  /** Probability per known kind — the UI shows the runner-up when unsure. */
  probabilities: Partial<Record<PaperKind, number>>;
}

/** Model provenance, surfaced in the scanner's info row. */
export const MODEL_INFO = {
  version: weights.version,
  trainedAt: weights.trainedAt,
  params: weights.sizes.slice(1).reduce((sum, size, i) => sum + size * (weights.sizes[i] + 1), 0),
  metrics: weights.metrics,
} as const;

let validated = false;

/**
 * Check the shipped model against the code that feeds it.
 *
 * Runs once, lazily — importing `weights.json` must not cost work for modules
 * that merely re-export types, but no prediction happens before this passes.
 */
function ensureValid(): void {
  if (validated) return;
  const fix = "Re-run `node scripts/train-scanner-nn.mjs` to regenerate weights.json.";

  if (weights.version !== 1) throw new Error(`Unsupported scanner model version ${weights.version}. ${fix}`);
  if (weights.featureNames.length !== FEATURE_NAMES.length) {
    throw new Error(
      `Scanner model was trained on ${weights.featureNames.length} features but the code extracts ${FEATURE_NAMES.length}. ${fix}`,
    );
  }
  for (let i = 0; i < FEATURE_NAMES.length; i++) {
    if (weights.featureNames[i] !== FEATURE_NAMES[i]) {
      throw new Error(
        `Scanner model feature #${i} is "${weights.featureNames[i]}" but the code extracts "${FEATURE_NAMES[i]}". ${fix}`,
      );
    }
  }
  if (weights.sizes[0] !== FEATURE_NAMES.length) {
    throw new Error(`Scanner model input layer is ${weights.sizes[0]}, features are ${FEATURE_NAMES.length}. ${fix}`);
  }
  for (const cls of weights.classes) {
    if (!["exam", "assignment", "notes", "worksheet", "form", "other"].includes(cls)) {
      throw new Error(`Scanner model class "${cls}" is not a known PaperKind. ${fix}`);
    }
  }
  if (weights.sizes[weights.sizes.length - 1] !== weights.classes.length) {
    throw new Error("Scanner model output layer does not match its class list. ${fix}");
  }
  validated = true;
}

/**
 * Score a feature vector. Vector length and model input must agree — the MLP
 * checks that too, but the message here names the fix.
 */
export function predictKind(features: number[]): KindPrediction {
  ensureValid();
  if (features.length !== FEATURE_NAMES.length) {
    throw new Error(`Expected ${FEATURE_NAMES.length} scanner features, got ${features.length}`);
  }

  const probs = forward({ sizes: weights.sizes, layers: weights.layers }, features);
  const best = argmax(probs);
  const probabilities: Partial<Record<PaperKind, number>> = {};
  weights.classes.forEach((cls, i) => {
    probabilities[cls as PaperKind] = probs[i];
  });

  return {
    kind: (weights.classes[best] ?? "other") as PaperKind,
    confidence: probs[best] ?? 0,
    probabilities,
  };
}

/** Extract features and score in one call — the pipeline's entry point. */
export function classifyScan(input: ScanFeatureInput): KindPrediction {
  return predictKind(extractScanFeatures(input));
}
